import{_ as t,a,c as i,ac as o}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第一册：英语初阶 · Lesson 18 What are their jobs?","description":"学习 复数职业与 their，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 18 What are their jobs?","description":"学习 复数职业与 their，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 复数职业与 their，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 17 How do you do?","link":"/life/english/new-concept/book-1/unit-01/lesson-017"},"next":{"text":"第一册：英语初阶 · Lesson 19 Tired and thirsty","link":"/life/english/new-concept/book-1/unit-01/lesson-019"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 17 How do you do?","link":"/life/english/new-concept/book-1/unit-01/lesson-017"},"next":{"text":"第一册：英语初阶 · Lesson 19 Tired and thirsty","link":"/life/english/new-concept/book-1/unit-01/lesson-019"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-01/lesson-018.md","filePath":"life/english/new-concept/book-1/unit-01/lesson-018.md"}'),n={name:"life/english/new-concept/book-1/unit-01/lesson-018.md"};function r(s,e,l,h,c,d){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="第一册-英语初阶-·-lesson-18-what-are-their-jobs" tabindex="-1">第一册：英语初阶 · Lesson 18 What are their jobs? <a class="header-anchor" href="#第一册-英语初阶-·-lesson-18-what-are-their-jobs" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 18 What are their jobs?&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-01/overview">单元 1</a> · <a href="/life/english/new-concept/book-1/unit-01/lesson-017">配套课 Lesson 17</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>向团队成员作介绍 本课要掌握复数职业与 their，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。本课将前一课的结构迁移到另一个例子；请先口头作答，再写出完整句子，不只替换单个单词。</p><p>本课为配套句型训练；先回顾相邻奇数课，再独立完成本页的原创练习。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>assistant</td><td>/əˈsɪstənt/</td><td>n.</td><td>助理</td><td>office assistants</td></tr><tr><td>employee</td><td>/ɪmˈplɔɪiː/</td><td>n.</td><td>雇员</td><td>new employees</td></tr><tr><td>their</td><td>/ðeə/</td><td>限定词</td><td>他们的</td><td>their office</td></tr><tr><td>office</td><td>/ˈɒfɪs/</td><td>n.</td><td>办公室</td><td>an office</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>their jobs — 多人的职业</li><li>office assistants — 办公室助理</li></ul><h2 id="语法讲解-复数职业与-their" tabindex="-1">语法讲解：复数职业与 their <a class="header-anchor" href="#语法讲解-复数职业与-their" aria-label="Permalink to &quot;语法讲解：复数职业与 their&quot;">​</a></h2><p>their 用于说明“他们/她们/它们的”，后面既能接单数也能接复数名词，取决于被拥有的东西。多人职业可用 They are engineers；复数泛指职业不加 a/an。What are their jobs? 中 jobs 与 are 对应。介绍名单时用人名说明对象，再用 they 避免机械重复。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Their office is on the first floor.</p></blockquote><p>他们的办公室在一楼。</p><p>Their office 虽由多人拥有，但 office 仍是一个，因此用 is；on the first floor 是地点表语。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>their 不等于 they are；后者缩写为 they&#39;re。多人可以共用一个 office，不能只看 their 就加复数。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“Their office is on the first floor.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Their office is on the first floor. Maya and Leo are office assistants.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“向团队成员作介绍”写两至三句，再读给同伴听。至少使用一次复数职业与 their，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>Their office 虽由多人拥有，但 office 仍是一个，因此用 is；on the first floor 是地点表语。 Maya and Leo 是 and 连接的复数主语，are 后接复数职业 office assistants。office 作为名词修饰语保持单数。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>选择 their/they&#39;re：___ office is small.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Their</p><p><strong>解析：</strong> 按本课规则判断：their 用于说明“他们/她们/它们的”，后面既能接单数也能接复数名词，取决于被拥有的东西。多人职业可用 They are engineers；复数泛指职业不加 a/an。What are their jobs? 中 jobs 与 are 对应。介绍名单时用人名说明对象，再用 they 避免机械重复。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“他们的办公室在一楼。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Their office is on the first floor.</p><p><strong>解析：</strong> Their office 虽由多人拥有，但 office 仍是一个，因此用 is；on the first floor 是地点表语。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：Maya and Leo are office assistants.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 玛雅和利奥是办公室助理。</p><p><strong>解析：</strong> Maya and Leo 是 and 连接的复数主语，are 后接复数职业 office assistants。office 作为名词修饰语保持单数。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：复数职业与 their。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-017">上一课</a> · <a href="/life/english/new-concept/book-1/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-01/lesson-019">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const u=t(n,[["render",r]]);export{p as __pageData,u as default};
